const plans={day:'Mañana: salí de Tinogasta y visitá Orquera, Andacollo y el conjunto de Anillaco. Hacé una pausa para almorzar. Tarde: continuá hacia Watungasta y terminá en San Pedro y la Comandancia, en Fiambalá. Reservá una jornada completa y confirmá todas las aperturas.',half:'Seleccioná menos paradas: Orquera, el conjunto de Anillaco y San Pedro, por ejemplo. Calculá al menos 4–5 horas para el circuito con paradas tranquilas. Si el tiempo es corto, evitá apurar visitas y elegí con un guía local.',two:'Día 1: Tinogasta, Orquera, Andacollo y Anillaco, con tiempo para gastronomía y artesanías locales. Día 2: Watungasta, San Pedro y Comandancia de Armas. Podés sumar las termas en otra franja, según disponibilidad y accesos.'};
const reduceMotion=matchMedia('(prefers-reduced-motion: reduce)').matches;
const route=$('route'), total=route.getTotalLength();
const storage={read(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}},write(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true}catch{return false}}};
const loaded=storage.read('adobe-stamps-v2',[]);
const collected=new Set(Array.isArray(loaded)?loaded.filter(x=>Number.isInteger(x)&&x>0&&x<stops.length):[]);
let active=0, target=0, rendered=0, frameId=0, previousTime=0, playing=false, dialogIndex=1, pointerX=0, pointerY=0, toastTimer, audioContext, soundGain, soundEnabled=false;
let viewport={width:innerWidth,height:innerHeight,worldWidth:0,worldHeight:0,left:0,top:0};
const markers=[], progressButtons=[];
const ns='http://www.w3.org/2000/svg';
function svgElement(tag,attrs){const el=document.createElementNS(ns,tag);for(const [k,v] of Object.entries(attrs))el.setAttribute(k,v);return el}
stops.forEach((s,i)=>{
 const point=route.getPointAtLength(s.t*total);
 const marker=svgElement('g',{class:'map-stop',transform:`translate(${point.x},${point.y})`,role:'button',tabindex:'0','aria-label':`Explorar ${s.name}`});
 marker.append(svgElement('circle',{class:'marker-ring',r:21}),svgElement('circle',{class:'marker-core',r:13}));
 const n=svgElement('text',{y:1});n.textContent=String(i).padStart(2,'0');marker.append(n);
 const label=svgElement('text',{class:'marker-label',y:-37});label.textContent=s.short;marker.append(label);
 marker.addEventListener('click',()=>jump(i));marker.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();jump(i)}});
 $('map-stops').append(marker);markers.push(marker);
 const button=document.createElement('button');button.title=s.name;button.setAttribute('aria-label',`Ir a ${s.name}`);button.addEventListener('click',()=>jump(i));$('progress-stops').append(button);progressButtons.push(button);
});
$('route-done').style.strokeDasharray=String(total);
function measure(){const w=$('world');viewport={width:innerWidth,height:$('game').clientHeight,worldWidth:w.offsetWidth,worldHeight:w.offsetHeight,left:w.offsetLeft,top:w.offsetTop};requestFrame()}
function scrollRange(){return Math.max(1,$('scroll-track').offsetHeight-$('game').clientHeight)}
function readScroll(){target=Math.max(0,Math.min(1,scrollY/scrollRange()));requestFrame()}
function requestFrame(){if(!frameId)frameId=requestAnimationFrame(render)}
function setPlaying(value){playing=value;$('play').textContent=value?'Ⅱ':'▶';$('play').setAttribute('aria-pressed',String(value));$('play').setAttribute('aria-label',value?'Pausar vuelo automático':'Iniciar vuelo automático');if(value){if(target>=.999){window.scrollTo(0,0);target=0}previousTime=performance.now();requestFrame()}}
function render(time){
 frameId=0;const delta=Math.min(40,time-previousTime||16);previousTime=time;
 if(playing){target=Math.min(1,target+delta/65000);window.scrollTo(0,target*scrollRange());if(target>=1)setPlaying(false)}
 rendered=reduceMotion?target:rendered+(target-rendered)*(1-Math.exp(-delta/120));
 if(Math.abs(rendered-target)<.00005)rendered=target;
 const p=route.getPointAtLength(rendered*total),next=route.getPointAtLength(Math.min(total,rendered*total+3)),prev=route.getPointAtLength(Math.max(0,rendered*total-3));
 const angle=Math.atan2(next.y-prev.y,next.x-prev.x)*180/Math.PI+90;
 $('plane-position').setAttribute('transform',`translate(${p.x},${p.y})`);$('plane').setAttribute('transform',`rotate(${angle}) scale(${viewport.width<=720?.43:1})`);
 $('route-done').style.strokeDashoffset=String(total*(1-rendered));
 const mobile=viewport.width<=720;
 const scale=Math.max(viewport.worldWidth/1600,viewport.worldHeight/1000);
 const planeScreenX=viewport.left+(viewport.worldWidth-1600*scale)/2+p.x*scale;
 const planeScreenY=viewport.top+(viewport.worldHeight-1000*scale)/2+p.y*scale;
 const clamp=(v,lo,hi)=>Math.max(lo,Math.min(hi,v));
 const tx=mobile?clamp(viewport.width*.5-planeScreenX,viewport.width-viewport.left-viewport.worldWidth,-viewport.left):(800-p.x)*.07;
 const ty=mobile?clamp(viewport.height*.43-planeScreenY,viewport.height-viewport.top-viewport.worldHeight,-viewport.top):(510-p.y)*.18;
 $('world').style.transform=`translate(${tx+pointerX}px,${ty+pointerY}px)`;
 $('progress-fill').style.width=`${rendered*100}%`;$('flight-percent').textContent=String(Math.round(rendered*100));
 $('game').classList.toggle('in-flight',rendered>.025);$('game').classList.toggle('complete',rendered>.99);
 let nearest=0;for(let i=1;i<stops.length;i++)if(Math.abs(stops[i].t-rendered)<Math.abs(stops[nearest].t-rendered))nearest=i;
 if(nearest!==active)updateCard(nearest);
 if(playing||rendered!==target)requestFrame();
}
function updateCard(index){
 active=index;const s=stops[index];$('card-photo').src=`assets/${s.image}.webp`;$('card-photo').alt=index?s.name:'Oratorio de los Orquera';$('card-tag').textContent=s.tag;$('card-number').textContent=String(index).padStart(2,'0');$('card-place').textContent=s.place.toUpperCase();$('card-title').textContent=s.title||s.name;$('card-description').textContent=s.description;
 $('visit').innerHTML=index?'Explorar este lugar <span>✦</span>':'Despegar <span>✦</span>';
 $('flight-label').textContent=index===0?'LISTO PARA DESPEGAR':index===7?'LLEGASTE A FIAMBALÁ':`EXPLORANDO · ${s.place.toUpperCase()}`;
 markers.forEach((m,i)=>m.classList.toggle('active',i===index));progressButtons.forEach((b,i)=>{b.classList.toggle('active',i===index);b.setAttribute('aria-current',i===index?'step':'false')});$('previous').disabled=index===0;$('next').disabled=index===stops.length-1;
}
function jump(index){if(!Number.isInteger(index)||index<0||index>=stops.length)return;setPlaying(false);window.scrollTo({top:stops[index].t*scrollRange(),behavior:reduceMotion?'instant':'smooth'});}
function openDialog(id){setPlaying(false);$(id).showModal();document.documentElement.style.overflow='hidden'}
function closeDialog(dialog){dialog.close()}
document.querySelectorAll('dialog').forEach(d=>{d.querySelector('.close-dialog').addEventListener('click',()=>closeDialog(d));d.addEventListener('close',()=>{document.documentElement.style.overflow='';measure()});d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog(d)}})});
function openPlace(index){if(index<1||index>=stops.length)return;dialogIndex=index;const s=stops[index];$('place-image').src=`assets/${s.image}.webp`;$('place-image').alt=s.name;$('place-label').textContent=`PARADA ${String(index).padStart(2,'0')} / ${s.place.toUpperCase()}`;$('place-title').textContent=s.name;$('place-story').textContent=s.story;$('place-tip').textContent=s.tip;$('hotspot-note').textContent=s.detail;$('hotspot-note').hidden=true;$('hotspot').setAttribute('aria-expanded','false');$('place-map').href=`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(s.query)}`;updateCollect();openDialog('place-dialog')}
function updateCollect(){$('collect').disabled=collected.has(dialogIndex);$('collect').innerHTML=collected.has(dialogIndex)?'Sello guardado ✓':'Guardar sello en mi pasaporte <span>✦</span>'}
function updatePassport(){
 $('stamp-count').textContent=`${collected.size}/7`;$('stamp-grid').replaceChildren();
 stops.slice(1).forEach((s,j)=>{const i=j+1,b=document.createElement('button');b.className=`stamp${collected.has(i)?' collected':''}`;b.setAttribute('aria-label',`${s.name}: ${collected.has(i)?'sello guardado':'sin descubrir'}`);const n=document.createElement('b');n.textContent=String(i).padStart(2,'0');const label=document.createElement('span');label.textContent=s.short;b.append(n,label);b.addEventListener('click',()=>{closeDialog($('passport-dialog'));jump(i);openPlace(i)});$('stamp-grid').append(b)});
 $('passport-status').textContent=collected.size===7?'Expedición completa. Te llevás siete historias del valle.':`${collected.size} de 7 historias en tu pasaporte. El camino continúa.`;
 progressButtons.forEach((b,i)=>b.classList.toggle('collected',collected.has(i)));
}
function toast(message){clearTimeout(toastTimer);$('toast').textContent=message;$('toast').classList.add('visible');toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),3000)}
$('collect').addEventListener('click',()=>{collected.add(dialogIndex);const saved=storage.write('adobe-stamps-v2',[...collected]);updateCollect();updatePassport();toast(saved?'✦ Una nueva historia en tu pasaporte':'Sello guardado durante esta visita');if(soundEnabled)chime()});
$('hotspot').addEventListener('click',()=>{const hidden=!$('hotspot-note').hidden;$('hotspot-note').hidden=hidden;$('hotspot').setAttribute('aria-expanded',String(!hidden))});
$('visit').addEventListener('click',()=>active?openPlace(active):jump(1));$('home').addEventListener('click',()=>jump(0));$('next').addEventListener('click',()=>jump(active+1));$('previous').addEventListener('click',()=>jump(active-1));$('play').addEventListener('click',()=>setPlaying(!playing));
$('continue').addEventListener('click',()=>{closeDialog($('place-dialog'));if(dialogIndex<7)jump(dialogIndex+1);else{updatePassport();openDialog('passport-dialog')}});
$('passport-open').addEventListener('click',()=>{updatePassport();openDialog('passport-dialog')});$('guide-open').addEventListener('click',()=>openDialog('guide-dialog'));$('about-open').addEventListener('click',()=>openDialog('about-dialog'));
$('download').addEventListener('click',()=>{const lines=['ADOBE · MI BITÁCORA DE VIAJE','Tinogasta — Fiambalá · Catamarca · Argentina','Recorrido aproximado: 55 km. Una jornada completa.','',...stops.slice(1).map((s,j)=>`${collected.has(j+1)?'[DESCUBIERTO]':'[POR DESCUBRIR]'} ${j+1}. ${s.name} — ${s.place}\n${s.story}\nPara visitar: ${s.tip}\nMapa: https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(s.query)}\n`),'ITINERARIO SUGERIDO',plans.day,'','Confirmá horarios, tarifas y accesos con Turismo local. Este recorrido ilustrado no es un mapa de navegación.','https://www.visittinogasta.tur.ar/turismo/rutas/ruta-del-adobe'];const url=URL.createObjectURL(new Blob(['\uFEFF'+lines.join('\n')],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='mi-bitacora-ruta-del-adobe.txt';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500)});
function selectPlan(plan){if(!Object.hasOwn(plans,plan))return;$('plan-text').textContent=plans[plan];document.querySelectorAll('[data-plan]').forEach(b=>{const selected=b.dataset.plan===plan;b.classList.toggle('selected',selected);b.setAttribute('aria-pressed',String(selected))})}
document.querySelectorAll('[data-plan]').forEach(b=>b.addEventListener('click',()=>selectPlan(b.dataset.plan)));selectPlan('day');
const checks=storage.read('adobe-checklist-v2',[]);document.querySelectorAll('.checklist input').forEach((input,i)=>{input.checked=Array.isArray(checks)&&checks.includes(i);input.addEventListener('change',()=>storage.write('adobe-checklist-v2',[...document.querySelectorAll('.checklist input')].flatMap((x,j)=>x.checked?[j]:[])))});
async function toggleSound(){try{if(!audioContext){const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio)throw new Error('No audio');audioContext=new Audio();const buffer=audioContext.createBuffer(1,audioContext.sampleRate*3,audioContext.sampleRate);const data=buffer.getChannelData(0);let brown=0;for(let i=0;i<data.length;i++){brown=(brown+(Math.random()*2-1)*.025)/1.025;data[i]=brown*3}const noise=audioContext.createBufferSource();noise.buffer=buffer;noise.loop=true;const filter=audioContext.createBiquadFilter();filter.type='lowpass';filter.frequency.value=600;soundGain=audioContext.createGain();soundGain.gain.value=0;noise.connect(filter).connect(soundGain).connect(audioContext.destination);noise.start()}await audioContext.resume();soundEnabled=!soundEnabled;soundGain.gain.setTargetAtTime(soundEnabled?.16:0,audioContext.currentTime,.5);$('sound').setAttribute('aria-pressed',String(soundEnabled));$('sound').setAttribute('aria-label',soundEnabled?'Silenciar sonido ambiente':'Activar sonido ambiente')}catch{toast('El sonido no está disponible en este navegador.')}}
function chime(){if(!audioContext)return;[523,659,784].forEach((frequency,i)=>{const o=audioContext.createOscillator(),g=audioContext.createGain(),t=audioContext.currentTime+i*.12;o.frequency.value=frequency;g.gain.setValueAtTime(.045,t);g.gain.exponentialRampToValueAtTime(.001,t+.7);o.connect(g).connect(audioContext.destination);o.start(t);o.stop(t+.75)})}
$('sound').addEventListener('click',toggleSound);$('fullscreen').addEventListener('click',async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen()}catch{toast('La pantalla completa no está disponible aquí.')}});
addEventListener('scroll',readScroll,{passive:true});addEventListener('resize',measure);addEventListener('wheel',()=>{if(playing)setPlaying(false)},{passive:true});addEventListener('touchstart',()=>{if(playing)setPlaying(false)},{passive:true});
addEventListener('keydown',e=>{if(document.querySelector('dialog[open]')||['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName))return;if(['ArrowDown','ArrowRight','PageDown'].includes(e.key)){e.preventDefault();jump(active+1)}if(['ArrowUp','ArrowLeft','PageUp'].includes(e.key)){e.preventDefault();jump(active-1)}if(e.key==='Home'){e.preventDefault();jump(0)}if(e.key==='End'){e.preventDefault();jump(7)}});
addEventListener('pointermove',e=>{if(reduceMotion||innerWidth<=720||e.pointerType==='touch')return;pointerX=(e.clientX/innerWidth-.5)*9;pointerY=(e.clientY/innerHeight-.5)*6;requestFrame()},{passive:true});
document.addEventListener('visibilitychange',()=>{if(document.hidden){setPlaying(false);audioContext?.suspend()}else if(soundEnabled)audioContext?.resume()});
// Feature-detected WebMCP uses exactly the same journey actions as the visible controls.
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'explore_adobe_stop',title:'Explorar una parada',description:'Selecciona una parada de la Ruta del Adobe y abre su historia; no guarda sellos.',inputSchema:{type:'object',properties:{stop:{type:'integer',minimum:1,maximum:7}},required:['stop'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||!Number.isInteger(input.stop)||input.stop<1||input.stop>7)throw new Error('La parada debe ser un entero entre 1 y 7.');if(document.querySelector('dialog[open]'))throw new Error('Cerrá la ventana actual antes de explorar otra parada.');jump(input.stop);openPlace(input.stop);return{stop:input.stop,name:stops[input.stop].name,opened:true}}})).catch(()=>{})}catch{}}
